"use strict";(self.webpackChunklifewell_docs=self.webpackChunklifewell_docs||[]).push([["5558"],{71183(e){e.exports=JSON.parse('{"tag":{"label":"features","permalink":"/tags/features","allTagsPath":"/tags","count":10,"items":[{"id":"features/blood-donation","title":"Blood donation","description":"A public directory of donors, requests that reach them, and a contact release that is given once to one person and can be withdrawn.","permalink":"/features/blood-donation"},{"id":"features/calendar-and-appointments","title":"Calendar and appointments","description":"One calendar for the ordinary week and the medical one, with a checklist on each appointment for the questions you meant to ask.","permalink":"/features/calendar-and-appointments"},{"id":"features/community-and-chats","title":"Community and chats","description":"Groups with posts and replies, one-to-one messages between connected accounts, blocking, and a moderation route that never tells an author who reported them.","permalink":"/features/community-and-chats"},{"id":"features/maps","title":"Maps and places","description":"Your own record plotted where it happened \u2014 memories, notes, people and events \u2014 plus saved places and an opt-in location history.","permalink":"/features/maps"},{"id":"features/professionals","title":"Professionals","description":"A directory of practitioners who listed themselves. LifeWell does not check anyone\'s qualifications \u2014 it prints the registration number and links to the register so you can check it yourself.","permalink":"/features/professionals"},{"id":"features/reminders","title":"Reminders","description":"What LifeWell may send you, when, and on which device \u2014 three master switches, quiet hours, and why the app never asks Android for an exact alarm.","permalink":"/features/reminders"},{"id":"features/search","title":"Search","description":"One search across your whole record. The server half is built; the page is not finished yet, and the app says so rather than showing an empty result list.","permalink":"/features/search"},{"id":"features/referrals","title":"The referral programme","description":"Invite someone, and a confirmed sign-up earns points, a badge and \u2014 past a threshold \u2014 a month of a paid plan. Every number is an admin setting rather than a constant.","permalink":"/features/referrals"},{"id":"features/shopping-list","title":"The shopping list","description":"A list built from your meals and recipes or written by hand, and shared as plain text so the person doing the shop needs no account.","permalink":"/features/shopping-list"},{"id":"features/tools","title":"Tools and calculators","description":"Which calculators live in LifeWell, which live on ZTools, and why the tools directory is mostly a set of links rather than re-implementations.","permalink":"/features/tools"}],"unlisted":false}}')}}]);